/// A styled button component
#[derive(IntoElement)]
pub struct Button {
    id: ElementId,
    label: SharedString,
    variant: ButtonVariant,
    size: ButtonSize,
    disabled: bool,
    selected: bool,
    full_width: bool,
    icon_left: Option<SharedString>,
    icon_right: Option<SharedString>,
    theme: Option<ButtonTheme>,
    design: Option<Arc<DesignSystem>>,
    on_click: Option<Rc<dyn Fn(&ClickEvent, &mut Window, &mut App) + 'static>>,
    aria_label: Option<SharedString>,
    aria_role: Option<AriaRole>,
}

impl Button {
    /// Create a new button with a label
    pub fn new(id: impl Into<ElementId>, label: impl Into<SharedString>) -> Self {
        Self {
            id: id.into(),
            label: label.into(),
            variant: ButtonVariant::default(),
            size: ButtonSize::default(),
            disabled: false,
            selected: false,
            full_width: false,
            icon_left: None,
            icon_right: None,
            theme: None,
            design: None,
            on_click: None,
            aria_label: None,
            aria_role: None,
        }
    }

    /// Set the button variant
    pub fn variant(mut self, variant: ButtonVariant) -> Self {
        self.variant = variant;
        self
    }

    /// Set the button size
    pub fn size(mut self, size: ButtonSize) -> Self {
        self.size = size;
        self
    }

    /// Disable the button
    pub fn disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    /// Set button selected state (for toggle buttons)
    pub fn selected(mut self, selected: bool) -> Self {
        self.selected = selected;
        self
    }

    /// Make button full width
    pub fn full_width(mut self, full_width: bool) -> Self {
        self.full_width = full_width;
        self
    }

    /// Add an icon to the left of the label
    pub fn icon_left(mut self, icon: impl Into<SharedString>) -> Self {
        self.icon_left = Some(icon.into());
        self
    }

    /// Add an icon to the right of the label
    pub fn icon_right(mut self, icon: impl Into<SharedString>) -> Self {
        self.icon_right = Some(icon.into());
        self
    }

    /// Set custom theme colors
    pub fn theme(mut self, theme: ButtonTheme) -> Self {
        self.theme = Some(theme);
        self
    }

    /// Set an explicit design system override.
    pub fn design(mut self, design: impl Into<Arc<DesignSystem>>) -> Self {
        self.design = Some(design.into());
        self
    }

    /// Set the click handler that ignores the event payload.
    ///
    /// Use this when the handler doesn't need the `ClickEvent` itself —
    /// e.g. simple state updates, navigation, dispatching app actions.
    /// For handlers that integrate with `cx.listener(|view, event, ...|)`,
    /// use [`Self::on_click_event`] instead, which takes the same 3-arg
    /// shape that `cx.listener` produces.
    pub fn on_click(mut self, handler: impl Fn(&mut Window, &mut App) + 'static) -> Self {
        let handler = Rc::new(handler);
        self.on_click = Some(Rc::new(move |_event: &ClickEvent, window, cx| {
            handler(window, cx);
        }));
        self
    }

    /// Set the click handler with access to the `ClickEvent` payload.
    ///
    /// Matches the signature `cx.listener(...)` produces, so call sites
    /// that previously did `.build().on_click(cx.listener(...))` can drop
    /// the `.build()` and call this directly:
    ///
    /// ```ignore
    /// Button::new("save", "Save")
    ///     .theme(theme.to_button_theme())
    ///     .on_click_event(cx.listener(|view, _: &ClickEvent, _window, cx| {
    ///         view.save(cx);
    ///     }))
    /// ```
    pub fn on_click_event(
        mut self,
        handler: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_click = Some(Rc::new(handler));
        self
    }

    /// Set an explicit ARIA label (overrides the button's text label)
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }

    /// Override the default ARIA role (Button)
    pub fn aria_role(mut self, role: AriaRole) -> Self {
        self.aria_role = Some(role);
        self
    }

    /// Compute colors based on variant and selected state
    /// Returns (bg, bg_hover, text_color, border_color)
    fn compute_colors(
        variant: ButtonVariant,
        selected: bool,
        theme: &ButtonTheme,
    ) -> (Rgba, Rgba, Rgba, Rgba) {
        if selected {
            (
                theme.accent,
                theme.accent_hover,
                theme.text_on_accent,
                theme.accent,
            )
        } else {
            match variant {
                ButtonVariant::Primary => (
                    theme.accent,
                    theme.accent_hover,
                    theme.text_on_accent,
                    theme.accent,
                ),
                ButtonVariant::Secondary => (
                    theme.surface,
                    theme.surface_hover,
                    theme.text_secondary,
                    theme.surface,
                ),
                ButtonVariant::Destructive => (
                    theme.error,
                    theme.error_hover,
                    theme.text_on_accent,
                    theme.error,
                ),
                ButtonVariant::Ghost => (
                    theme.transparent,
                    theme.surface_hover,
                    theme.text_secondary,
                    theme.transparent,
                ),
                ButtonVariant::Outline => (
                    theme.transparent,
                    theme.surface,
                    theme.text_secondary,
                    theme.border,
                ),
            }
        }
    }

    fn padding_for_size(size: ButtonSize, design: &DesignSystem) -> (Pixels, Pixels) {
        let px_base = design.spacing.control_padding_x;
        let py_base = design.spacing.control_padding_y;
        match size {
            ButtonSize::Xs => (px(px_base * 0.5), px(py_base * 0.35)),
            ButtonSize::Sm => (px(px_base * 0.7), px(py_base * 0.55)),
            ButtonSize::Md => (px(px_base), px(py_base * 0.75)),
            ButtonSize::Lg => (px(px_base * 2.0), px(py_base * 1.5)),
        }
    }

    fn text_size_for_size(size: ButtonSize, design: &DesignSystem) -> Pixels {
        match size {
            ButtonSize::Xs | ButtonSize::Sm => px(design.typography.small_size),
            ButtonSize::Md => px(design.typography.base_size),
            ButtonSize::Lg => px(design.typography.large_size),
        }
    }

    /// Build the button into a `Stateful<Div>` that can have additional handlers added.
    /// Use this when you need to add a cx.listener() handler.
    ///
    /// Note: This bypasses accessibility registration. Prefer using the component
    /// directly via `RenderOnce` for automatic accessibility tree integration.
    pub fn build(self) -> Stateful<Div> {
        let design = self
            .design
            .clone()
            .unwrap_or_else(crate::design::neutral_design);
        let theme = self.theme.clone().unwrap_or_default();
        self.build_with_theme_and_design(&theme, &design)
    }

    /// Build with explicit theme and design defaults.
    pub fn build_with_theme_and_design(
        self,
        theme: &ButtonTheme,
        design: &DesignSystem,
    ) -> Stateful<Div> {
        let (bg, bg_hover, text_color, border_color) =
            Self::compute_colors(self.variant, self.selected, theme);

        let (px_val, py_val) = Self::padding_for_size(self.size, design);
        let text_size = Self::text_size_for_size(self.size, design);

        let mut el = div()
            .id(self.id)
            .flex()
            .items_center()
            .justify_center()
            .gap_2()
            .px(px_val)
            .py(py_val)
            .rounded(px(design.corners.md))
            .text_size(text_size)
            .bg(bg)
            .text_color(text_color)
            .border_1()
            .border_color(border_color);

        // Apply full width
        if self.full_width {
            el = el.w_full();
        }

        if self.disabled {
            el = el.opacity(0.5).cursor_not_allowed();
        } else {
            el = el.cursor_pointer().hover(|style| style.bg(bg_hover));
        }

        // Add icon left
        if let Some(icon) = self.icon_left {
            el = el.child(icon);
        }

        // Add label
        el = el.child(self.label);

        // Add icon right
        if let Some(icon) = self.icon_right {
            el = el.child(icon);
        }

        el
    }
}

impl RenderOnce for Button {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        // Register in accessibility tree
        cx.register_accessible(AccessibilityNode {
            element_id: self.id.clone(),
            label: self
                .aria_label
                .clone()
                .unwrap_or_else(|| self.label.clone()),
            props: AriaProps::with_role(self.aria_role.unwrap_or(AriaRole::Button))
                .maybe_state(self.disabled, AriaState::Disabled)
                .maybe_state(self.selected, AriaState::Pressed(true)),
        });

        let global_theme = cx.theme();
        let design = crate::design::resolve_design(self.design.clone(), cx);
        let theme = self
            .theme
            .unwrap_or_else(|| ButtonTheme::from(&global_theme));
        let (bg, bg_hover, text_color, border_color) =
            Self::compute_colors(self.variant, self.selected, &theme);

        let (px_val, py_val) = Self::padding_for_size(self.size, &design);
        let text_size = Self::text_size_for_size(self.size, &design);

        // Get/create persistent focus handle for this button id so the
        // element is Tab-reachable across re-renders. See module-level
        // BUTTON_FOCUS_HANDLES comment for the registry pattern.
        let focus_handle = button_focus_handle(&self.id, cx);
        let focus_ring_color = theme.accent;

        let mut el = div()
            .id(self.id.clone())
            .track_focus(&focus_handle)
            .font_family(global_theme.font_family.clone())
            .flex()
            .items_center()
            .justify_center()
            .gap_2()
            .px(px_val)
            .py(py_val)
            .rounded(px(design.corners.md))
            .text_size(text_size)
            .bg(bg)
            .text_color(text_color)
            .border_1()
            .border_color(border_color)
            .cursor_pointer()
            // CSS `:focus-visible` analogue — only renders when the user
            // arrived at the button via keyboard (Tab), not via mouse click.
            // Layered on top of the base border, so a focused button has a
            // 2px accent-colored ring distinct from its normal border_color.
            .focus_visible(|style| style.border_2().border_color(focus_ring_color));

        // Apply text size based on button size
        el = match self.size {
            ButtonSize::Xs => el.text_xs(),
            ButtonSize::Sm => el.text_xs(),
            ButtonSize::Md => el.text_sm(),
            ButtonSize::Lg => el.text_lg(),
        };

        // Apply full width
        if self.full_width {
            el = el.w_full();
        }

        if self.disabled {
            el = el.opacity(0.5).cursor_not_allowed();
        } else {
            el = el.hover(move |style| style.bg(bg_hover).shadow(glow_shadow(bg_hover)));
            if let Some(handler) = self.on_click {
                let mouse_handler = handler.clone();
                el = el.on_click(move |event: &ClickEvent, window, cx| {
                    mouse_handler(event, window, cx);
                });
                // Keyboard activation — Enter and Space mirror the click
                // handler with a synthesized `ClickEvent::Keyboard` payload.
                // Required for WCAG 2.1.1 (Keyboard accessible).
                let key_handler = handler;
                el = el.on_key_down(move |event: &KeyDownEvent, window, cx| {
                    let key = event.keystroke.key.as_str();
                    if key == "enter" || key == "space" {
                        let click = ClickEvent::Keyboard(KeyboardClickEvent::default());
                        key_handler(&click, window, cx);
                        cx.stop_propagation();
                    }
                });
            }
        }

        // Add icon left
        if let Some(icon) = self.icon_left {
            el = el.child(icon);
        }

        // Add label
        el = el.child(self.label);

        // Add icon right
        if let Some(icon) = self.icon_right {
            el = el.child(icon);
        }

        el
    }
}
